select energy_manager.load_cards($cards$[
{"id":"p2-063","paper":2,"topic":"Refractories","kind":"fact","front":"What is the significance of bulk density of a refractory?","back":"Higher bulk density means lower porosity: higher strength, better resistance to slag penetration and higher heat capacity, but lower insulating value.","explain":"Low-density refractories are better insulators and store less heat but are weaker. Bulk density is therefore chosen to balance strength/durability against insulation for the application.","flash":false,"source":"BEE 2024 P2 L2(a)","order":2062},
{"id":"p2-064","paper":2,"topic":"Refractories","kind":"fact","front":"What are monolithic refractories and their benefits?","back":"Unshaped refractories (castables, plastics, ramming mixes, gunning mixes) installed as a joint-free lining.","explain":"Without joints there are fewer weak spots; installation and repair are faster (gunning can be done hot), shapes are flexible, storage is easier and downtime is reduced. They have largely replaced bricks in many furnace applications.","flash":false,"source":"BEE 2024 P2 L2(b)","order":2063},
{"id":"p2-065","paper":2,"topic":"FBC boilers","kind":"fact","front":"Which basic type of FBC boiler is called the 'bubbling bed' boiler?","back":"AFBC – atmospheric fluidised bed combustion.","explain":"The three main types are AFBC (bubbling bed at atmospheric pressure), CFBC (circulating bed with higher velocity and solids recirculation through cyclones) and PFBC (pressurised, which can drive a gas turbine).","flash":false,"source":"BEE 2024 P2 Q40","order":2064},
{"id":"p2-066","paper":2,"topic":"FBC boilers","kind":"fact","front":"In an FBC boiler, what is the fuel burnt in?","back":"A bed of inert granular material (sand, ash, limestone) kept fluidised by air blown up through a distributor.","explain":"The hot bed has huge thermal inertia and intense mixing, so even low-grade, high-ash or wet fuels burn steadily at a modest bed temperature.","flash":false,"source":"BEE 2025 P2 Q31","order":2065},
{"id":"p2-067","paper":2,"topic":"FBC boilers","kind":"fact","front":"Why is limestone or dolomite added to the bed of an FBC boiler?","back":"To capture sulphur – it reacts with SO₂ to form calcium sulphate, reducing SO₂ emissions.","explain":"Bed temperatures of about 800–900 °C are ideal for this sulphur capture reaction, so FBC can burn high-sulphur fuels without flue gas desulphurisation.","flash":true,"source":"BEE 2024 P2 Q22","order":2066},
{"id":"p2-068","paper":2,"topic":"FBC boilers","kind":"fact","front":"List the main advantages of FBC boilers.","back":"High combustion efficiency, fuel flexibility (low-grade, high-ash, biomass fuels), lower NOx (low bed temperature), in-bed SO₂ capture, compact size, and no clinker formation.","explain":"Combustion at around 800–900 °C is below ash fusion temperature, avoiding clinkers, and limits thermal NOx. The main drawback is higher fan power to fluidise the bed.","flash":false,"source":"BEE 2024 P2 Q21; BEE 2025 P2 Q30, Q49","order":2067},
{"id":"p2-069","paper":2,"topic":"FBC boilers","kind":"fact","front":"In FBC, match: primary air, secondary air, tertiary air, air distributor, combustion temperature.","back":"Primary air – instant combustion as fuel enters; secondary air – complete combustion of volatiles; tertiary air – turbulence and burnout of residual volatiles; air distributor – prevents channelling, uniform reaction; combustion temperature – governs NOx formation.","explain":"This matching question appeared directly in the exam. The distributor plate ensures uniform fluidisation, and keeping bed temperature moderate is what keeps NOx low.","flash":false,"source":"BEE 2024 P2 S1","order":2068},
{"id":"p2-070","paper":2,"topic":"Cogeneration","kind":"fact","front":"What is cogeneration (CHP)?","back":"Sequential production of electrical/mechanical power and useful heat from the same fuel source.","explain":"By using heat that a power-only plant would reject, cogeneration can reach overall fuel utilisation of 70–85%+ versus roughly 30–40% for separate power generation, reducing fuel consumption and emissions.","flash":false,"source":"BEE 2025 P2 Q1, Q17","order":2069},
{"id":"p2-071","paper":2,"topic":"Cogeneration","kind":"fact","front":"Distinguish a topping cycle from a bottoming cycle.","back":"Topping: fuel first produces power, and the rejected heat serves the process. Bottoming: fuel first supplies high-temperature process heat, and the waste heat then generates power.","explain":"Topping cycles are by far the most common. Bottoming cycles suit very high temperature processes such as cement kilns, steel and glass furnaces; a low-temperature process (e.g. a sugar mill at ~120 °C) is not suited to bottoming.","flash":true,"source":"BEE 2024 P2 Q37, Q38; BEE 2025 P2 S2","order":2070},
{"id":"p2-072","paper":2,"topic":"Cogeneration","kind":"fact","front":"Define heat-to-power ratio.","back":"Ratio of the thermal energy to the electrical energy required by (or produced for) a facility, in the same units.","explain":"It is the key parameter for choosing a cogeneration system. Back-pressure steam turbines suit high heat-to-power ratios, gas turbines and reciprocating engines suit lower ratios, and combined cycle the lowest.","flash":false,"source":"BEE 2024 P2 Q28; BEE 2025 P2 S2","order":2071},
{"id":"p2-073","paper":2,"topic":"Cogeneration","kind":"fact","front":"What is a back-pressure turbine and what is an extraction-condensing turbine?","back":"Back-pressure: all steam exhausts at a pressure suitable for process use. Extraction-condensing: part of the steam is extracted for process and the rest condenses to produce extra power.","explain":"Back-pressure units have high overall efficiency but power output is tied to process steam demand. Extraction-condensing units give flexibility to vary heat and power independently, at the cost of condenser losses.","flash":false,"source":"BEE 2025 P2 Q50","order":2072},
{"id":"p2-074","paper":2,"topic":"Cogeneration","kind":"fact","front":"In a combined cycle plant, what is the gas turbine exhaust heat used for?","back":"To generate steam in a Heat Recovery Steam Generator (HRSG) to drive a steam turbine.","explain":"Gas turbine exhaust is typically around 450–550 °C, ideal for an HRSG. Gas turbine plus steam turbine in series gives the high efficiency of combined cycle plants.","flash":false,"source":"BEE 2025 P2 Q32, L3","order":2073},
{"id":"p2-075","paper":2,"topic":"Cogeneration","kind":"fact","front":"How are heat rate and efficiency related?","back":"Inverse: efficiency (%) = 860 / heat rate (kcal/kWh) × 100. Lower heat rate = higher efficiency.","explain":"Heat rate is fuel heat input per kWh generated. Example: 3050 kcal/kWh → 28.2%. Auxiliary power % = (1 − gross heat rate / net heat rate) × 100, e.g. 2100/2282 → about 8%.","flash":true,"source":"BEE 2025 P2 Q2; BEE 2024 P2 Q27, S8","order":2074},
{"id":"p2-076","paper":2,"topic":"Cogeneration","kind":"fact","front":"Define steam turbine cylinder efficiency.","back":"Ratio of actual enthalpy drop to isentropic enthalpy drop across the turbine (or cylinder).","explain":"It measures internal losses; a decline indicates blade erosion, deposits or seal leakage. It differs from overall efficiency, which also includes mechanical, gearbox and generator losses.","flash":false,"source":"BEE 2024 P2 Q41","order":2075},
{"id":"p2-077","paper":2,"topic":"Cogeneration","kind":"fact","front":"Define Energy Utilisation Factor (EUF) for a cogeneration plant.","back":"EUF = (Electrical output + Useful thermal output) / Fuel energy input.","explain":"EUF counts heat and power equally. A back-pressure cogeneration scheme may reach 70%+ while a condensing power plant plus separate boiler gives much less, because condenser heat is wasted.","flash":false,"source":"BEE 2024 P2 L6; BEE 2025 P2 L5","order":2076},
{"id":"p2-078","paper":2,"topic":"Cogeneration","kind":"problem","front":"A gas turbine cogeneration unit produces 4 MW of power at a heat rate of 3,000 kcal/kWh, firing natural gas of GCV 8,500 kcal/sm³. Its exhaust feeds an HRSG producing 9 t/h of steam (enthalpy 665 kcal/kg) from feed water at 105 °C. Find gas consumption, electrical efficiency, energy utilisation factor and heat-to-power ratio.","back":"Gas ≈ 1,412 sm³/h; electrical efficiency ≈ 28.7%; EUF ≈ 70.7%; heat-to-power ≈ 1.47","explain":"Heat rate × power gives fuel heat input; dividing by GCV gives fuel flow. Electrical efficiency = 860/heat rate. Recovered HRSG heat plus power over fuel input gives EUF; heat-to-power ratio compares useful heat with electricity in the same units (1 MW = 860,000 kcal/h).","steps":[{"prompt":"Fuel heat input.","answer":"4,000 kW × 3,000 = 12,000,000 kcal/h (13.95 MW)","explain":"Heat rate × power."},{"prompt":"Gas consumption.","answer":"12,000,000/8,500 = 1,412 sm³/h","explain":"Heat input / GCV."},{"prompt":"Electrical efficiency.","answer":"860/3,000 = 28.7%","explain":"η = 860/heat rate."},{"prompt":"HRSG heat recovered.","answer":"9,000 × (665 − 105) = 5,040,000 kcal/h = 5.86 MW","explain":"Steam × enthalpy rise; ÷ 860,000 for MW."},{"prompt":"EUF and heat-to-power ratio.","answer":"EUF = (4 + 5.86)/13.95 = 70.7%; H:P = 5.86/4 = 1.47","explain":"EUF = (power + useful heat)/fuel input."}],"flash":false,"source":"Based on BEE 2024 P2 S8, L6","order":2077},
{"id":"p2-079","paper":2,"topic":"Cogeneration","kind":"problem","front":"A plant needs 2 MW of power and 6 MW of process heat. Scheme 1: a boiler (82% efficient) feeds a condensing turbine producing 2 MW at 30% overall conversion of steam heat to power, and separately supplies the 6 MW process heat. Scheme 2: a boiler (80% efficient) feeds a back-pressure turbine that converts 88% of its steam enthalpy drop to 2 MW; the exhaust meets the 6 MW process load. Compare fuel input, EUF and % fuel saving.","back":"Scheme 1: fuel ≈ 15.45 MW, EUF ≈ 51.8%; Scheme 2: fuel ≈ 10.34 MW, EUF ≈ 77.4%; back-pressure cogeneration saves ≈ 33.1% fuel","explain":"In the condensing scheme most of the turbine steam's heat is rejected in the condenser, so the boiler must produce far more heat. In the back-pressure scheme the turbine exhaust is itself the process steam, so only the power-generation enthalpy drop (plus its small losses) is extra. This is the core reason cogeneration has a high energy utilisation factor.","steps":[{"prompt":"Scheme 1 boiler output.","answer":"Power steam = 2/0.30 = 6.67 MW; + 6 MW process = 12.67 MW","explain":"Separate power and heat paths."},{"prompt":"Scheme 1 fuel and EUF.","answer":"Fuel = 12.67/0.82 = 15.45 MW; EUF = (2 + 6)/15.45 = 51.8%","explain":"EUF = useful output / fuel input."},{"prompt":"Scheme 2 boiler output.","answer":"(x − 6) × 0.88 = 2 → x = 8.27 MW","explain":"Enthalpy drop to power at 88%; exhaust provides 6 MW."},{"prompt":"Scheme 2 fuel and EUF.","answer":"Fuel = 8.27/0.80 = 10.34 MW; EUF = 8/10.34 = 77.4%","explain":"Same definition."},{"prompt":"% fuel saving.","answer":"(15.45 − 10.34)/15.45 = 33.1%","explain":"Relative reduction in fuel input."}],"flash":false,"source":"Based on BEE 2025 P2 L5","order":2078},
{"id":"p2-080","paper":2,"topic":"Heat exchangers","kind":"fact","front":"Write the LMTD formula and say which flow arrangement gives the larger LMTD.","back":"LMTD = (ΔT₁ − ΔT₂) / ln(ΔT₁/ΔT₂); counter-flow gives a larger LMTD than parallel flow for the same terminal temperatures.","explain":"For counter-flow, ΔT₁ = T_h,in − T_c,out and ΔT₂ = T_h,out − T_c,in. Example: hot 150→100, cold 50→70 gives ΔT₁ = 80, ΔT₂ = 50 and LMTD ≈ 64 °C. If ΔT₁ = ΔT₂, LMTD equals that difference.","flash":false,"source":"BEE 2024 P2 Q25, Q30; BEE 2025 P2 S8","order":2079},
{"id":"p2-081","paper":2,"topic":"Heat exchangers","kind":"fact","front":"Define heat exchanger effectiveness.","back":"ε = Actual heat transfer / Maximum possible heat transfer, where Q_max = C_min × (T_hot,in − T_cold,in).","explain":"C_min is the smaller of (m × Cp) of the two streams. Effectiveness lies between 0 and 1 and allows comparison of exchangers regardless of flow arrangement.","flash":false,"source":"BEE 2024 P2 S4; BEE 2025 P2 Q33","order":2080},
{"id":"p2-082","paper":2,"topic":"Heat exchangers","kind":"fact","front":"What is the terminal temperature difference (TTD) in a steam-to-water heater?","back":"Steam saturation temperature minus the outlet water temperature.","explain":"A rising TTD indicates fouling, air blanketing or poor venting/draining in feed water heaters and condensers.","flash":false,"source":"BEE 2025 P2 Q5","order":2081},
{"id":"p2-083","paper":2,"topic":"Heat exchangers","kind":"fact","front":"What is the 'pinch point' in pinch analysis?","back":"The point of minimum temperature difference between the composite hot and cold streams.","explain":"Pinch analysis sets minimum hot and cold utility targets for a process. The rules: do not transfer heat across the pinch, no external cooling above the pinch and no external heating below it.","flash":false,"source":"BEE 2025 P2 Q34","order":2082},
{"id":"p2-084","paper":2,"topic":"Heat exchangers","kind":"fact","front":"In a cross-flow heat exchanger, how do the hot and cold fluids flow, and what is the role of baffles in a shell-and-tube exchanger?","back":"Cross-flow: the two fluids flow perpendicular to each other. Baffles direct the shell-side fluid across the tubes, supporting the tubes and increasing turbulence/heat transfer.","explain":"Parallel flow has both fluids in the same direction, counter-flow in opposite directions. Baffles add pressure drop but raise the shell-side heat transfer coefficient and prevent tube vibration.","flash":false,"source":"BEE 2024 P2 Q24, Q48","order":2083},
{"id":"p2-085","paper":2,"topic":"Waste heat recovery","kind":"fact","front":"What is a recuperator?","back":"A heat exchanger in which heat passes continuously from flue gas to combustion air through a separating metallic or ceramic wall.","explain":"Metallic radiation recuperators (concentric tubes) preheat combustion air from high-temperature flue gas; convective recuperators use tube banks. Ceramic tube recuperators handle higher gas temperatures (around 1550 °C) where metal would fail.","flash":false,"source":"BEE 2025 P2 Q3, L3","order":2084},
{"id":"p2-086","paper":2,"topic":"Waste heat recovery","kind":"fact","front":"What is a regenerator?","back":"A heat store (brick checkerwork) that is alternately heated by flue gas and then gives this heat to incoming cold air; two chambers operate in alternation.","explain":"Regenerators suit very high temperature, large furnaces such as glass furnaces and blast furnace stoves. Efficiency depends on the cycle reversal time and the heat capacity of the checkerwork.","flash":false,"source":"BEE 2025 P2 L3","order":2085},
{"id":"p2-087","paper":2,"topic":"Waste heat recovery","kind":"fact","front":"What are a heat wheel and a heat pipe?","back":"Heat wheel: a slowly rotating porous disc that transfers heat between two separate gas streams. Heat pipe: a sealed tube in which a working fluid evaporates at the hot end and condenses at the cold end, transferring heat with no moving parts.","explain":"Heat wheels suit low-to-medium temperature air streams such as HVAC exhaust. Heat pipes have very high effective conductance, need no external power and are compact and reliable.","flash":false,"source":"BEE 2025 P2 L3; BEE 2024 P2 L4","order":2086},
{"id":"p2-088","paper":2,"topic":"Waste heat recovery","kind":"fact","front":"What does a heat pump do in waste heat recovery?","back":"It upgrades low-temperature waste heat to a higher useful temperature using mechanical (or thermal) work.","explain":"A heat pump works like a refrigeration cycle in reverse use: heat absorbed at the evaporator from a low-temperature source, plus compressor work, is delivered at the condenser at a higher temperature.","flash":false,"source":"BEE 2024 P2 Q4; BEE 2025 P2 L3","order":2087},
{"id":"p2-089","paper":2,"topic":"Waste heat recovery","kind":"fact","front":"How do multiple-effect evaporators save energy?","back":"Vapour produced in one effect is used as the heating steam for the next effect operating at lower pressure, so 1 kg of live steam evaporates several kg of water.","explain":"Each effect runs at lower pressure (and boiling point) than the previous one, allowing reuse of latent heat. Steam economy rises roughly in proportion to the number of effects, at the cost of more heat-transfer area.","flash":false,"source":"BEE 2024 P2 S7","order":2088},
{"id":"p2-090","paper":2,"topic":"Waste heat recovery","kind":"problem","front":"A hot effluent stream (5 kg/s, Cp 4.18 kJ/kg·K) at 90 °C preheats boiler make-up water (4 kg/s, Cp 4.18 kJ/kg·K) from 30 °C to 60 °C in a counter-flow heat exchanger with U = 900 W/m²·K. Neglecting losses, find (a) heat duty, (b) effluent exit temperature, (c) LMTD and required area, (d) effectiveness.","back":"(a) 501.6 kW; (b) 66.0 °C; (c) LMTD ≈ 32.9 °C, area ≈ 16.9 m²; (d) ε ≈ 50.0%","explain":"Heat gained by the cold stream equals heat lost by the hot stream. LMTD uses the two terminal temperature differences of the counter-flow arrangement, and area = Q/(U × LMTD). Effectiveness compares actual duty with the maximum possible, C_min × (T_h,in − T_c,in); here the water has the smaller capacity rate.","steps":[{"prompt":"Heat duty from the cold side.","answer":"Q = 4 × 4.18 × (60 − 30) = 501.6 kW","explain":"Q = m·Cp·ΔT."},{"prompt":"Effluent exit temperature.","answer":"T = 90 − 501.6/(5 × 4.18) = 66.0 °C","explain":"Energy balance on hot side."},{"prompt":"LMTD (counter-flow).","answer":"ΔT₁ = 90 − 60 = 30, ΔT₂ = 66.0 − 30 = 36.0; LMTD = (36.0 − 30)/ln(36.0/30) = 32.9 °C","explain":"LMTD = (ΔT₁ − ΔT₂)/ln(ΔT₁/ΔT₂)."},{"prompt":"Required area.","answer":"A = 501,600 / (900 × 32.9) = 16.9 m²","explain":"A = Q/(U·LMTD), Q in W."},{"prompt":"Effectiveness.","answer":"C_min = 4 × 4.18 = 16.72 kW/K; Q_max = 16.72 × (90 − 30) = 1,003.2 kW; ε = 501.6/1,003.2 = 50.0%","explain":"ε = Q/Q_max."}],"flash":false,"source":"Based on BEE 2025 P2 L1; BEE 2024 P2 S4","order":2089},
{"id":"p3-001","paper":3,"topic":"Electrical system & tariff","kind":"fact","front":"Why is power transmitted over long distances at high voltage?","back":"For the same power, current falls as voltage rises, so I²R line losses fall roughly with 1/V².","explain":"Power P = √3·V·I·cosφ; doubling voltage halves current for the same power, cutting resistive losses to a quarter. This is why generation at 11–33 kV is stepped up for transmission and stepped down at substations, whose main role is voltage transformation. HVDC is preferred for very long distances because it avoids reactive power flow and has lower losses there.","flash":false,"source":"BEE 2024 P3 Q28","order":3000},
{"id":"p3-002","paper":3,"topic":"Electrical system & tariff","kind":"fact","front":"A plant receives 96 MU at its end and the T&D efficiency is 80%. How much generation is required?","back":"120 MU (= 96 / 0.80).","explain":"Energy delivered = energy generated × T&D efficiency, so generation = delivered ÷ efficiency. A common trap is to multiply (96 × 0.8 = 76.8) instead of dividing. The 24 MU difference is the T&D loss.","flash":false,"source":"BEE 2025 P3 Q48","order":3001},
{"id":"p3-003","paper":3,"topic":"Electrical system & tariff","kind":"fact","front":"How is the AT&C (Aggregate Technical & Commercial) loss of a distribution utility calculated?","back":"AT&C loss = 1 − (Billing efficiency × Collection efficiency).","explain":"Billing efficiency = energy billed (metered + unmetered assessed) ÷ input energy. Collection efficiency = amount actually collected for current bills (excluding arrears) ÷ amount billed. Example: billing 80% and collection 75% gives AT&C loss = 1 − 0.6 = 40%. Revenue realised per kWh input = current collections ÷ input energy.","flash":false,"source":"BEE 2025 P3 S-2","order":3002},
{"id":"p3-004","paper":3,"topic":"Electrical system & tariff","kind":"fact","front":"What makes up a two-part industrial electricity tariff?","back":"A demand charge (on contract or recorded maximum demand, Rs/kVA or Rs/kW per month) plus an energy charge (Rs/kWh).","explain":"The demand charge recovers the utility's fixed capacity cost, the energy charge its running cost. Many tariffs add power-factor incentives or penalties and Time-of-Day (ToD) rates. Lowering MD and improving PF therefore cut the bill even when kWh is unchanged.","flash":false,"source":"syllabus","order":3003},
{"id":"p3-005","paper":3,"topic":"Electrical system & tariff","kind":"fact","front":"What is the purpose of a Time-of-Day (ToD) tariff?","back":"To shift consumption from peak hours to off-peak hours by charging more for peak energy and less for off-peak energy.","explain":"Utilities face their highest purchase cost at the evening peak. Consumers can save by rescheduling flexible loads (pumping, batch processes, thermal or ice storage) to night. A DISCOM can also pay incentives for load shifting: net saving = (peak cost − off-peak cost − incentive) × kWh shifted.","flash":false,"source":"BEE 2025 P3 L-3","order":3004},
{"id":"p3-006","paper":3,"topic":"Electrical system & tariff","kind":"fact","front":"How is Maximum Demand (MD) recorded by a utility meter?","back":"As the highest average kVA (or kW) over any demand integration interval in the billing month, typically 15 or 30 minutes.","explain":"Because MD is an average over the interval, a short motor-start spike matters less than sustained simultaneous loading. MD can be reduced by staggering loads, load shedding with an MD controller, rescheduling non-critical loads, using captive generation at peak, and improving PF (which lowers kVA for the same kW).","flash":false,"source":"syllabus","order":3005},
{"id":"p3-007","paper":3,"topic":"Electrical system & tariff","kind":"fact","front":"Define load factor and explain why a high load factor is desirable.","back":"Load factor = average load ÷ maximum demand over a period. A high load factor spreads the fixed demand charge over more kWh, lowering the average cost per unit.","explain":"Average load = kWh consumed ÷ hours in the period. For example, 2,00,000 kWh in a 720-hour month with MD 500 kW gives load factor = 277.8/500 = 55.6%. Flattening the load profile raises load factor and lets the same supply infrastructure serve more energy.","flash":false,"source":"syllabus","order":3006},
{"id":"p3-008","paper":3,"topic":"Power factor","kind":"fact","front":"What does a power factor of unity mean?","back":"No reactive power (kVAr) is drawn from the supply; kVA equals kW and current is in phase with voltage.","explain":"Power factor = kW/kVA = cos φ. Inductive loads such as motors and transformers draw lagging magnetising current, so PF is below 1. At unity PF the supply current is the minimum possible for the given real power.","flash":false,"source":"BEE 2025 P3 Q42","order":3007},
{"id":"p3-009","paper":3,"topic":"Power factor","kind":"fact","front":"What is the formula for the capacitor kVAr needed to raise PF from cos φ1 to cos φ2?","back":"kVAr = kW × (tan φ1 − tan φ2).","explain":"The real power (kW) stays the same; only the reactive component is reduced. Find φ = cos⁻¹(PF) for each PF and take the tangent. Multiplier tables in BEE books list (tan φ1 − tan φ2) directly; for example, 0.75 → 0.95 gives 0.553.","flash":true,"source":"syllabus","order":3008},
{"id":"p3-010","paper":3,"topic":"Power factor","kind":"fact","front":"How does a capacitor bank improve the power factor?","back":"It supplies leading reactive power locally, offsetting the lagging kVAr drawn by inductive loads, so less kVAr (and current) comes from the supply.","explain":"The capacitor does not change the kW of the load. The net kVAr seen upstream of the capacitor falls, so kVA and current fall. That releases transformer and cable capacity, reduces I²R losses and improves voltage.","flash":false,"source":"BEE 2024 P3 Q31","order":3009},
{"id":"p3-011","paper":3,"topic":"Power factor","kind":"fact","front":"If the tail-end power factor is improved from 0.80 to 0.95, by what percentage do distribution (I²R) losses fall?","back":"About 29%. Losses scale with 1/PF², so the reduction = 1 − (0.80/0.95)² = 0.29.","explain":"For constant kW and voltage, current ∝ 1/PF, so I²R losses ∝ 1/PF². New losses = (0.8/0.95)² ≈ 0.709 of the original. Capacitors deliver this saving only on the network upstream of where they are connected, so installing them at the load (tail) end maximises the loss reduction.","flash":true,"source":"BEE 2025 P3 Q40","order":3010},
{"id":"p3-012","paper":3,"topic":"Power factor","kind":"problem","front":"A plant draws 500 kW at 0.75 PF lagging. It installs capacitors to raise the PF to 0.95. Find the capacitor kVAr needed, the kVA demand before and after, and the percentage reduction in distribution losses upstream of the capacitors.","back":"Capacitor ≈ 277 kVAr; kVA falls from 666.7 to 526.3 (≈ 140 kVA MD reduction); upstream I²R losses fall by ≈ 37.7%.","explain":"PF correction leaves kW unchanged and removes reactive kVAr, so kVA and current both fall. Because losses scale with the square of the current, a 21% current reduction gives about a 38% loss reduction. This calculation underlies every 'MD reduction by PF improvement' question.","steps":[{"prompt":"Find tan φ1 and tan φ2.","answer":"tan(cos⁻¹0.75) = 0.882; tan(cos⁻¹0.95) = 0.329","explain":"tan φ = √(1 − PF²)/PF."},{"prompt":"Calculate the capacitor rating.","answer":"kVAr = 500 × (0.882 − 0.329) = 500 × 0.553 ≈ 277 kVAr","explain":"kVAr = kW × (tan φ1 − tan φ2)."},{"prompt":"Calculate the kVA before and after correction.","answer":"Before: 500/0.75 = 666.7 kVA; after: 500/0.95 = 526.3 kVA","explain":"kVA = kW / PF."},{"prompt":"Find the MD reduction.","answer":"666.7 − 526.3 = 140.4 kVA","explain":"The demand charge is billed on kVA, so this reduction cuts the monthly bill directly."},{"prompt":"Find the loss reduction.","answer":"1 − (0.75/0.95)² = 1 − 0.623 = 37.7%","explain":"I ∝ 1/PF, so I²R ∝ 1/PF²."}],"flash":false,"source":"syllabus","order":3011},
{"id":"p3-013","paper":3,"topic":"Power factor","kind":"problem","front":"A factory at 6.6 kV supplies an arc furnace (1000 kW at 0.70 PF lag), induction motors (600 kW at 0.80 PF lag) and lighting (150 kW at unity PF). Find the total kW, the resultant kVA and PF, and the capacitor kVAr needed to reach 0.95 PF lag.","back":"1750 kW; ≈ 2286 kVA; PF ≈ 0.766; capacitor ≈ 895 kVAr.","explain":"When loads run at different power factors, add the kW and the kVAr separately and then combine them vectorially: kVA = √(kW² + kVAr²). Simply adding the individual kVA values overstates the total (here 2329 vs 2286 kVA). The capacitor size is the existing kVAr minus the kVAr allowed at the target PF.","steps":[{"prompt":"Find the total real power.","answer":"1000 + 600 + 150 = 1750 kW","explain":"kW adds arithmetically."},{"prompt":"Find each load's kVAr.","answer":"Furnace: 1000 × tan(cos⁻¹0.70) = 1000 × 1.020 = 1020 kVAr; motors: 600 × 0.75 = 450 kVAr; lighting: 0. Total ≈ 1470 kVAr","explain":"kVAr = kW × tan φ."},{"prompt":"Find the resultant kVA and PF.","answer":"kVA = √(1750² + 1470²) ≈ 2286 kVA; PF = 1750/2286 ≈ 0.766","explain":"Combine vectorially."},{"prompt":"Find the kVAr allowed at 0.95 PF.","answer":"1750 × 0.329 ≈ 575 kVAr","explain":"tan(cos⁻¹0.95) = 0.329."},{"prompt":"Find the capacitor size.","answer":"1470 − 575 ≈ 895 kVAr","explain":"Equivalently, 1750 × (tan(cos⁻¹0.766) − 0.329)."}],"flash":false,"source":"BEE 2025 P3 S-5 (similar)","order":3012},
{"id":"p3-014","paper":3,"topic":"Transformers","kind":"fact","front":"What are the two main types of transformer loss, and how does each vary with load?","back":"No-load (core/iron) loss is roughly constant whenever the transformer is energised. Load (copper, I²R) loss varies with the square of the load.","explain":"Core loss is hysteresis plus eddy-current loss in the laminations and depends on voltage and frequency, not load. Copper loss at x per-unit load = x² × full-load copper loss. Total loss = NL + x²·FL_Cu. A lightly loaded transformer is therefore dominated by its core loss.","flash":true,"source":"syllabus","order":3013},
{"id":"p3-015","paper":3,"topic":"Transformers","kind":"fact","front":"A 750 kVA transformer has 1200 W no-load loss and 7200 W full-load copper loss. What is its total loss at 60% load?","back":"3792 W (= 1200 + 0.6² × 7200 = 1200 + 2592).","explain":"Only the copper loss is scaled, and by the square of the load fraction. A common error is to scale it linearly (giving 5520 W).","flash":false,"source":"BEE 2025 P3 Q7","order":3014},
{"id":"p3-016","paper":3,"topic":"Transformers","kind":"fact","front":"At what load does a transformer reach maximum efficiency?","back":"When copper (load) loss equals core (no-load) loss, at a per-unit load of √(No-load loss / Full-load copper loss).","explain":"For NL = 1.8 kW and FL Cu = 10.5 kW, the maximum efficiency occurs at √(1.8/10.5) = 0.414, i.e. about 41% load. Distribution transformers are designed for peak efficiency at part load because they spend much time lightly loaded.","flash":false,"source":"syllabus","order":3015},
{"id":"p3-017","paper":3,"topic":"Transformers","kind":"fact","front":"What do amorphous-core transformers mainly reduce?","back":"No-load (core) losses.","explain":"Amorphous metal has very low hysteresis loss and high resistivity (low eddy currents), so core loss is far below that of CRGO steel. They suit distribution transformers that stay energised 24 hours a day at low average load. Load (copper) losses are not inherently reduced.","flash":false,"source":"BEE 2025 P3 Q17","order":3016}
]$cards$::jsonb);
